    65→/**
    66→ * The KeyStoreManager loads the IDSKeyStore and provides the TrustManager.
    67→ */
    68→@Slf4j
    69→@Getter
    70→public class KeyStoreManager {
    71→
    72→    /**
    73→     * The TrustStoreManager.
    74→     */
    75→    @Setter
    76→    private TrustStoreManager trustStoreManager = new TrustStoreManager();
    77→
    78→    /**
    79→     * The ConfigurationModel.
    80→     */
    81→    private ConfigurationModel configurationModel;
    82→
    83→    /**
    84→     * The keystore.
    85→     */
    86→    private KeyStore keyStore;
    87→
    88→    /**
    89→     * The keystore password.
    90→     */
    91→    private char[] keyStorePw;
    92→
    93→    /**
    94→     * The alias.
    95→     */
    96→    private String keyAlias;
    97→
    98→    /**
    99→     * The truststore.
   100→     */
   101→    private KeyStore trustStore;
   102→
   103→    /**
   104→     * The truststore password.
   105→     */
   106→    private char[] trustStorePw;
   107→
   108→    /**
   109→     * The private key.
   110→     */
   111→    private PrivateKey privateKey;
   112→
   113→    /**
   114→     * The Certificate.
   115→     */
   116→    private Certificate cert;
   117→
   118→    /**
   119→     * The X509TrustManager.
   120→     */
   121→    private X509TrustManager trustManager;
   122→
   123→    /**
   124→     * Build the KeyStoreManager from the given configuration.
   125→     *
   126→     * @param configurationModel A ConfigurationModel.
   127→     * @param keystorePw The password for the IDSKeyStore.
   128→     * @param trustStorePw The password for the IDSTrustStore.
   129→     * @param keyAlias The alias of the IDS PrivateKey.
   130→     * @throws KeyStoreManagerInitializationException When the KeyStoreManager cannot be initialized
   131→     */
   132→    public KeyStoreManager(final ConfigurationModel configurationModel,
   133→                           final char[] keystorePw,
   134→                           final char[] trustStorePw,
   135→                           final String keyAlias) throws KeyStoreManagerInitializationException {
   136→        try {
   137→            if (log.isDebugEnabled()) {
   138→                log.debug("Initializing KeyStoreManager... [code=(IMSCOD0090)]");
   139→            }
   140→            initClassVars(configurationModel, keystorePw, trustStorePw, keyAlias);
   141→        } catch (IOException e) {
   142→            throwKeyStoreInitException(e, "Key- or Truststore could not be loaded!"
   143→                                          + " [code=(IMSCOE0010)]");
   144→        } catch (CertificateException | NoSuchAlgorithmException e) {
   145→            throwKeyStoreInitException(e, "Error while loading a Certificate! [code=(IMSCOE0011)]");
   146→        } catch (UnrecoverableKeyException e) {
   147→            throwKeyStoreInitException(e,
   148→               "Could not initialize Key/Truststore: password is incorrect! [code=(IMSCOE0012)]");
   149→        } catch (KeyStoreException e) {
   150→            throwKeyStoreInitException(e, "Initialization of Key- or Truststore failed!"
   151→                                        + " [code=(IMSCOE0013)]");
   152→        }
   153→    }
   154→
   155→    /**
   156→     * Getter for the expiration date of the Cert in the KeyStore.
   157→     *
   158→     * @return Expiration of currently used IDS Certificate.
   159→     */
   160→    public Date getCertExpiration() {
   161→        return ((X509Certificate) cert).getNotAfter();
   162→    }
   163→
   164→    private void throwKeyStoreInitException(final Exception exception, final String message)
   165→            throws KeyStoreManagerInitializationException {
   166→        if (log.isErrorEnabled()) {
   167→            log.error(message);
   168→        }
   169→        throw new KeyStoreManagerInitializationException(exception.getMessage(),
   170→                                                         exception.getCause());
   171→    }
   172→
   173→    private void initClassVars(final ConfigurationModel configurationModel,
   174→                               final char[] keystorePw,
   175→                               final char[] trustStorePw,
   176→                               final String keyAlias) throws
   177→            CertificateException,
   178→            NoSuchAlgorithmException,
   179→            IOException,
   180→            KeyStoreException,
   181→            UnrecoverableKeyException,
   182→            KeyStoreManagerInitializationException {
   183→        this.configurationModel = configurationModel;
   184→        this.keyStorePw = keystorePw;
   185→        this.trustStorePw = trustStorePw;
   186→        this.keyAlias = keyAlias;
   187→
   188→        createKeyStore(configurationModel, keystorePw);
   189→        createTrustStore(configurationModel, trustStorePw);
   190→        initTrustManager(trustStorePw);
   191→        getPrivateKeyFromKeyStore(keyAlias);
   192→        initCertificateSubjectCn(); //requires valid connector certificate (e.g. issued by DAPS)
   193→        initCertificateConnectorFingerprint();
   194→    }
   195→
   196→    private void initCertificateSubjectCn()  {
   197→        try {
   198→            final var certificate = (X509Certificate) this.getCert();
   199→            final var x500name = new JcaX509CertificateHolder(certificate).getSubject();
   200→            final var cn = x500name.getRDNs(BCStyle.CN)[0];
   201→
   202→            //Set certificate subject cn
   203→            CertificateSubjectCnProvider.certificateSubjectCn
   204→                    = UUID.fromString(IETFUtils.valueToString(cn.getFirst().getValue()));
   205→        } catch (Exception exception) {
   206→            if (log.isDebugEnabled()) {
   207→                log.debug("Could not read Subject-CN UUID from the connector certificate."
   208→                         + " Valid connector certificate? Will generate random UUID."
   209→                         + " [code=(IMSCOD0091)]");
   210→            }
   211→
   212→            CertificateSubjectCnProvider.certificateSubjectCn = UUID.randomUUID();
   213→        }
   214→    }
   215→
   216→    /**
   217→     * Initialises the ConnectorFingerprintProvider fingerprint value (aki/ski) of the connector
   218→     * by the connector certificate.
   219→     */
   220→    private void initCertificateConnectorFingerprint() {
   221→        try {
   222→            ConnectorFingerprintProvider.fingerprint = Optional.of(getConnectorFingerprint());
   223→            if (log.isDebugEnabled()) {
   224→                log.debug("Determined AKI/SKI fingerprint of the connector. [code=(IMSCOD0150),"
   225→                          + " fingerprint=({})]",
   226→                         ConnectorFingerprintProvider.fingerprint.get());
   227→            }
   228→        } catch (Exception exception) {
   229→            ConnectorFingerprintProvider.fingerprint = Optional.empty();
   230→            if (log.isDebugEnabled()) {
   231→                log.debug("Could not determine AKI/SKI fingerprint of the connector."
   232→                         + " [code=(IMSCOD0151), error=({})]", exception.getMessage());
   233→            }
   234→        }
   235→    }
   236→
   237→    private void initTrustManager(final char... trustStorePw)
   238→            throws NoSuchAlgorithmException, KeyStoreException, UnrecoverableKeyException {
   239→        final var myManager = loadTrustManager(trustStorePw);
   240→        trustManager = trustStoreManager.configureTrustStore(myManager);
   241→    }
   242→
   243→    private void createTrustStore(final ConfigurationModel configurationModel,
   244→                                  final char... trustStorePw)
   245→            throws
   246→            CertificateException,
   247→            NoSuchAlgorithmException,
   248→            IOException,
   249→            KeyStoreManagerInitializationException {
   250→        trustStore = loadKeyStore(trustStorePw,
   251→                                  configurationModel.getTrustStore(),
   252→                                  "Truststore");
   253→    }
   254→
   255→    private void createKeyStore(final ConfigurationModel configurationModel,
   256→                                final char... keystorePw)
   257→            throws
   258→            CertificateException,
   259→            NoSuchAlgorithmException,
   260→            IOException,
   261→            KeyStoreManagerInitializationException {
   262→        keyStore = loadKeyStore(keystorePw, configurationModel.getKeyStore(), "Keystore");
   263→    }
   264→
   265→    /**
   266→     * Load a KeyStore from the given location and open it with the given password.
   267→     * Try to find it inside the jar first, if nothing is found there, try the path at system scope.
   268→     *
   269→     * @param pw Password of the keystore.
   270→     * @param location Path of the keystore.
   271→     * @param keyStoreType The type of the keystore (Keystore / Truststore).
   272→     * @return The IdsKeyStore as java keystore instance.
   273→     * @throws CertificateException If any of the certificates in the keystore could not be loaded.
   274→     * @throws NoSuchAlgorithmException If the algorithm used to check the integrity of the
   275→     * keystore cannot be found.
   276→     * @throws IOException When the Key-/Truststore File cannot be found.
   277→     */
   278→    private KeyStore loadKeyStore(final char[] pw, final URI location, final String keyStoreType)
   279→            throws
   280→            CertificateException,
   281→            NoSuchAlgorithmException,
   282→            IOException,
   283→            KeyStoreManagerInitializationException {
   284→
   285→        validateLocation(location, keyStoreType);
   286→
   287→        if (log.isDebugEnabled()) {
   288→            log.debug("Searching for keystore file. [code=(IMSCOD0092), location=({})]",
   289→                      location.toString());
   290→        }
   291→        final var store = getKeyStoreInstance();
   292→
   293→        if (store == null) {
   294→            return null;
   295→        }
   296→
   297→        final var pathString = Paths.get(location).toString();
   298→
   299→        //remove leading /, \ and . from path
   300→        final var relativepathString = pathString.chars().dropWhile(
   301→                value -> IntStream.of('\\', '/', '.')
   302→                                  .anyMatch(v -> v == value))
   303→                                  .collect(StringBuilder::new,
   304→                                          StringBuilder::appendCodePoint,
   305→                                          StringBuilder::append)
   306→                                  .toString();
   307→
   308→        if (log.isDebugEnabled()) {
   309→            log.debug("Determined relative path. [code=(IMSCOD0093), path=({})]",
   310→                      relativepathString);
   311→        }
   312→
   313→        final var keyStoreOnClassPath = new ClassPathResource(relativepathString).exists();
   314→
   315→        if (keyStoreOnClassPath) {
   316→            if (log.isDebugEnabled()) {
   317→                log.debug("Loading KeyStore from ClassPath... [code=(IMSCOD0094)]");
   318→            }
   319→            final var is = new ClassPathResource(relativepathString).getInputStream();
   320→            try {
   321→                store.load(is, pw);
   322→                is.close();
   323→            } catch (IOException e) {
   324→                if (log.isErrorEnabled()) {
   325→                    log.error("Could not find {} aborting! [code=(IMSCOE0014),"
   326→                              + " exception=({})]", keyStoreType, e.getMessage());
   327→                }
   328→                throwKeyStoreInitException(e, e.getMessage());
   329→            }
   330→        } else {
   331→            if (log.isDebugEnabled()) {
   332→                log.debug("Could not load keystore from classpath, trying"
   333→                    + " to find it at system scope! [code=(IMSCOD0095)]");
   334→            }
   335→            try {
   336→                if (log.isDebugEnabled()) {
   337→                    log.debug("System Path [code=(IMSCOD0096), path=({})]", pathString);
   338→                }
   339→
   340→                //try absolute path
   341→                final var fileOnSystemScope = new File(pathString).exists();
   342→
   343→                final FileInputStream fis;
   344→                if (fileOnSystemScope) {
   345→                    //if file at absolute path exists
   346→                    fis = new FileInputStream(pathString);
   347→                } else {
   348→                    //last try, relative path in system scope
   349→                    fis = new FileInputStream(relativepathString);
   350→                }
   351→
   352→                store.load(fis, pw);
   353→                fis.close();
   354→
   355→            } catch (IOException e) {
   356→                if (log.isErrorEnabled()) {
   357→                    log.error("Could not find {} at system scope, aborting! [code=(IMSCOE0015),"
   358→                              + " exception=({})]", keyStoreType, e.getMessage());
   359→                }
   360→                throwKeyStoreInitException(e, e.getMessage());
   361→            }
   362→        }
   363→        if (log.isInfoEnabled()) {
   364→            log.info("Successfully loaded {}. [code=(IMSCOI0049)]", keyStoreType);
   365→        }
   366→        return store;
   367→    }
   368→
   369→    /**
   370→     * Checks whether the keystore path specification is set in the connector configuration.
   371→     *
   372→     * @param location The keystore path.
   373→     * @param keyStoreType Indication whether it is keystore or truststore.
   374→     * @throws KeyStoreManagerInitializationException Thrown if location specification is not set.
   375→     */
   376→    private void validateLocation(final URI location, final String keyStoreType)
   377→            throws KeyStoreManagerInitializationException {
   378→        if (location == null) {
   379→            if (log.isErrorEnabled()) {
   380→                log.error("Location input for keystore-path from connector configuration"
   381→                          + " is not valid!"
   382→                         + " [code=(IMSCOE0016), type=({}), location=(null)]", keyStoreType);
   383→            }
   384→            throw new KeyStoreManagerInitializationException(
   385→                    "Location input for keystore-path is null! Type: " + keyStoreType);
   386→        }
   387→    }
   388→
   389→    @Nullable
   390→    private KeyStore getKeyStoreInstance() {
   391→        KeyStore store = null;
   392→        try {
   393→            store = KeyStore.getInstance(KeyStore.getDefaultType());
   394→        } catch (KeyStoreException e) {
   395→            if (log.isErrorEnabled()) {
   396→                log.error("Could not create a KeyStore with default type! [code=(IMSCOE0017),"
   397→                          + "exception=({})]", e.getMessage());
   398→            }
   399→        }
   400→        return store;
   401→    }
   402→
   403→    /**
   404→     * Load the TrustManager from the truststore.
   405→     *
   406→     * @param password Password of the truststore.
   407→     * @return The X509TrustManager for the certificates inside the Truststore.
   408→     * @throws NoSuchAlgorithmException If no Provider supports a TrustManagerFactorySpi
   409→     * implementation for the specified algorithm.
   410→     * @throws UnrecoverableKeyException If the key cannot be recovered
   411→     * (e.g. the given password is wrong).
   412→     * @throws KeyStoreException If initialization of the trustmanager fails.
   413→     */
   414→    private X509TrustManager loadTrustManager(final char... password)
   415→            throws NoSuchAlgorithmException, KeyStoreException, UnrecoverableKeyException {
   416→        if (log.isDebugEnabled()) {
   417→            log.debug("Loading trustmanager... [code=(IMSCOD0097)]");
   418→        }
   419→
   420→        final var keyManagerFactory = KeyManagerFactory
   421→                .getInstance(KeyManagerFactory.getDefaultAlgorithm());
   422→        keyManagerFactory.init(this.trustStore, password);
   423→
   424→        final var trustManagerFactory = TrustManagerFactory
   425→                .getInstance(TrustManagerFactory.getDefaultAlgorithm());
   426→        trustManagerFactory.init(this.trustStore);
   427→        final var trustManagers = trustManagerFactory.getTrustManagers();
   428→
   429→        if (log.isDebugEnabled()) {
   430→            log.debug("Successfully loaded the trustmanager using the TrustStore."
   431→                      + " [code=(IMSCOD0098)]");
   432→        }
   433→
   434→        if (trustManagers.length != 1 || !(trustManagers[0] instanceof X509TrustManager)) {
   435→            throw new IllegalStateException("Unexpected default trust"
   436→                + " managers:" + Arrays.toString(trustManagers));
   437→        }
   438→
   439→        return (X509TrustManager) trustManagers[0];
   440→    }
   441→
   442→    /**
   443→     * Get the PrivateKey from the KeyStore (use the Key with the given alias).
   444→     *
   445→     * @param keyAlias The alias of the PrivateKey to be loaded.
   446→     * @throws UnrecoverableKeyException If the Key cannot be retrieved
   447→     * from the keystore (e.g. the given password is wrong).
   448→     * @throws NoSuchAlgorithmException If the algorithm for recovering the key cannot be found.
   449→     * @throws KeyStoreException If KeyStore was not initialized or private key cannot be found.
   450→     */
   451→    private void getPrivateKeyFromKeyStore(final String keyAlias)
   452→            throws UnrecoverableKeyException, NoSuchAlgorithmException, KeyStoreException {
   453→
   454→        if (log.isDebugEnabled()) {
   455→            log.debug("Getting private key from keystore. [code=(IMSCOD0098), alias=({})]",
   456→                      keyAlias);
   457→        }
   458→        final var key = keyStore.getKey(keyAlias, keyStorePw);
   459→
   460→        if (key == null) {
   461→            if (log.isErrorEnabled()) {
   462→                log.error("Keystoremanager: No private key for the given alias found"
   463→                          + " within the Keystore! Given alias does not exist"
   464→                          + " or does not identify a key-related entry! [code=(IMSCOE0018),"
   465→                          + "alias=({})]", keyAlias);
   466→            }
   467→            throw new KeyStoreException("Keystoremanager: No private key for the given alias found"
   468→                                        + " within the Keystore! Given alias does not exist"
   469→                                        + " or does not identify a key-related entry! [alias=("
   470→                                        + keyAlias + ")]");
   471→        }
   472→
   473→        if (key instanceof PrivateKey) {
   474→            if (log.isDebugEnabled()) {
   475→                log.debug("Setting private key and connector certificate. [code=(IMSCOD0099)]");
   476→            }
   477→            this.privateKey = (PrivateKey) key;
   478→            this.cert = keyStore.getCertificate(keyAlias);
   479→        }
   480→    }
   481→
   482→    /**
   483→     * Generates the fingerprint of the Connector (UID) using the KeyStoreManager.
   484→     *
   485→     * @return The generated connector fingerprint (UID).
   486→     * @throws ConnectorMissingCertExtensionException Thrown if either AKI
   487→     * or SKI are not valid within the connector certificate.
   488→     */
   489→    private String getConnectorFingerprint()
   490→            throws ConnectorMissingCertExtensionException {
   491→        final var certificate = (X509Certificate) this.getCert();
   492→        final var authorityKeyIdentifier = getCertificateAKI(certificate);
   493→        final var subjectKeyIdentifier = getCertificateSKI(certificate);
   494→
   495→        return generateConnectorFingerprint(authorityKeyIdentifier, subjectKeyIdentifier);
   496→    }
   497→
   498→    /**
   499→     * Generates the fingerprint of the connector (UID).
   500→     *
   501→     * @param authorityKeyIdentifier The connector certificate AKI.
   502→     * @param subjectKeyIdentifier The connector certificate SKI.
   503→     * @return The generated fingerprint of the connector (UID).
   504→     */
   505→    private String generateConnectorFingerprint(final byte[] authorityKeyIdentifier,
   506→                                                final byte[] subjectKeyIdentifier) {
   507→        final var akiResult = beautifyHex(encodeHexString(authorityKeyIdentifier).toUpperCase());
   508→        final var skiResult = beautifyHex(encodeHexString(subjectKeyIdentifier).toUpperCase());
   509→
   510→        return skiResult + "keyid:" + akiResult.substring(0, akiResult.length() - 1);
   511→    }
   512→
   513→    /**
   514→     * Get the SKI of the certificate.
   515→     *
   516→     * @param cert The X509Certificate-Certificate
   517→     * @return The SKI-KeyIdentifier of the certificate
   518→     * @throws ConnectorMissingCertExtensionException thrown if SKI of certificate is empty
   519→     */
   520→    private byte[] getCertificateSKI(final X509Certificate cert)
   521→            throws ConnectorMissingCertExtensionException {
   522→        if (log.isDebugEnabled()) {
   523→            log.debug("Get SKI from certificate... [code=(IMSCOD0110)]");
   524→        }
   525→
   526→        final var skiOid = Extension.subjectKeyIdentifier.getId();
   527→        final var rawSubjectKeyIdentifier = cert.getExtensionValue(skiOid);
   528→
   529→        if (rawSubjectKeyIdentifier == null) {
   530→            throw new ConnectorMissingCertExtensionException(
   531→                    "SKI of the Connector Certificate is null!");
   532→        }
   533→
   534→        final var ski0c = ASN1OctetString.getInstance(rawSubjectKeyIdentifier);
   535→        final var ski = SubjectKeyIdentifier.getInstance(ski0c.getOctets());
   536→
   537→        return ski.getKeyIdentifier();
   538→    }
   539→
   540→    /**
   541→     * Get the AKI of the certificate.
   542→     *
   543→     * @param cert The X509Certificate-Certificate
   544→     * @return The AKI-KeyIdentifier of the Certificate
   545→     * @throws ConnectorMissingCertExtensionException thrown if AKI of certificate is empty
   546→     */
   547→    private byte[] getCertificateAKI(final X509Certificate cert)
   548→            throws ConnectorMissingCertExtensionException {
   549→        if (log.isDebugEnabled()) {
   550→            log.debug("Get AKI from certificate... [code=(IMSCOD0111)]");
   551→        }
   552→
   553→        final var akiOid = Extension.authorityKeyIdentifier.getId();
   554→        final var rawAuthorityKeyIdentifier = cert.getExtensionValue(akiOid);
   555→
   556→        checkEmptyRawAKI(rawAuthorityKeyIdentifier); //can throw exception
   557→
   558→        final var akiOc = ASN1OctetString.getInstance(rawAuthorityKeyIdentifier);
   559→        final var aki = AuthorityKeyIdentifier.getInstance(akiOc.getOctets());
   560→
   561→        return aki.getKeyIdentifier();
   562→    }
   563→
   564→    /**
   565→     * Checks if AKI is empty.
   566→     *
   567→     * @param rawAuthorityKeyIdentifier The AKI to check
   568→     * @throws ConnectorMissingCertExtensionException thrown if AKI of certificate is null
   569→     */
   570→    private void checkEmptyRawAKI(final byte[] rawAuthorityKeyIdentifier)
   571→            throws ConnectorMissingCertExtensionException {
   572→        if (rawAuthorityKeyIdentifier == null) {
   573→            throw new ConnectorMissingCertExtensionException(
   574→                    "AKI of the Connector Certificate is null!");
   575→        }
   576→    }
   577→
   578→    /**
   579→     * Beautifies Hex strings and will generate a result later used to
   580→     * create the client id (XX:YY:ZZ).
   581→     *
   582→     * @param hexString HexString to be beautified
   583→     * @return beautifiedHex result
   584→     */
   585→    private static String beautifyHex(final String hexString) {
   586→        return Arrays.stream(hexString.split("(?<=\\G..)"))
   587→                     .map(s -> s + ":")
   588→                     .collect(Collectors.joining());
   589→    }
